          subsidized_cost_decimal == o.subsidized_cost_decimal &&
          category_ids == o.category_ids &&
          status == o.status &&
          year == o.year &&
          catalog == o.catalog &&
          competency_ids == o.competency_ids &&
          total_training_cost == o.total_training_cost &&
          total_training_indirect_cost == o.total_training_indirect_cost &&
          total_training_salary_cost == o.total_training_salary_cost &&
          total_training_subsidized_cost == o.total_training_subsidized_cost &&
          total_participants == o.total_participants &&
          training_attendance_status == o.training_attendance_status &&
          valid_for == o.valid_for &&
          objectives == o.objectives &&
          number_of_expired_participants == o.number_of_expired_participants &&
          total_duration == o.total_duration &&
          is_mandatory == o.is_mandatory
    end

    # @see the `==` method
    # @param [Object] Object to be compared
    def eql?(o)
      self == o
    end

    # Calculates hash code according to all attributes.
    # @return [Integer] Hash code
    def hash
      [id, company_id, author_id, author_employee_id, name, code, description, created_at, updated_at, external_provider, external, total_cost, fundae_subsidized, subsidized, cost, subsidized_cost, total_cost_decimal, cost_decimal, subsidized_cost_decimal, category_ids, status, year, catalog, competency_ids, total_training_cost, total_training_indirect_cost, total_training_salary_cost, total_training_subsidized_cost, total_participants, training_attendance_status, valid_for, objectives, number_of_expired_participants, total_duration, is_mandatory].hash
    end

    # Builds the object from hash
    # @param [Hash] attributes Model attributes in the form of hash
    # @return [Object] Returns the model itself
    def self.build_from_hash(attributes)
      return nil unless attributes.is_a?(Hash)
      attributes = attributes.transform_keys(&:to_sym)
      transformed_hash = {}
      openapi_types.each_pair do |key, type|
        if attributes.key?(attribute_map[key]) && attributes[attribute_map[key]].nil?
          transformed_hash["#{key}"] = nil
        elsif type =~ /\AArray<(.*)>/i
          # check to ensure the input is an array given that the attribute
          # is documented as an array but the input is not
          if attributes[attribute_map[key]].is_a?(Array)
            transformed_hash["#{key}"] = attributes[attribute_map[key]].map { |v| _deserialize($1, v) }
          end
        elsif !attributes[attribute_map[key]].nil?
          transformed_hash["#{key}"] = _deserialize(type, attributes[attribute_map[key]])
        end
      end
      new(transformed_hash)
    end

    # Returns the object in the form of hash
    # @return [Hash] Returns the object in the form of hash
    def to_hash
      hash = {}
      self.class.attribute_map.each_pair do |attr, param|
        value = self.send(attr)
        if value.nil?
          is_nullable = self.class.openapi_nullable.include?(attr)
          next if !is_nullable || (is_nullable && !instance_variable_defined?(:"@#{attr}"))
        end

        hash[param] = _to_hash(value)
      end
      hash
    end

  end

